-- Athena saved query (Product_B2C_Intl)
-- ID: 268b4cb2-705d-4a33-81e7-2f798e246e7c
-- Name: Cohort Deals Organic order share of boosted listings - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp_sd AS ( SELECT s.mri_session_id, s.route_id, CAST(s.doj AS VARCHAR) AS doj, s.cohort_type, CASE WHEN s.channel_exp_info IS NULL THEN 'null' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant FROM "user_interaction"."search_route_details" s WHERE s.__time >= TIMESTAMP '2026-04-19 18:30:00' AND s.__time < TIMESTAMP '2026-04-29 18:30:00' AND s.country = 'IND' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.os = 'iOS' AND s.tp_channel = 'INVALID' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 ), session_exp AS ( SELECT mri_session_id, MAX(exp_variant) AS exp_variant FROM srp_sd GROUP BY 1 ), saw_boost_session AS ( SELECT DISTINCT mri_session_id FROM srp_sd WHERE cohort_type = 'BOOSTUI' ), boosted_route_tuple AS ( SELECT DISTINCT mri_session_id, route_id, doj FROM srp_sd WHERE cohort_type = 'BOOSTUI' ), confirm_ok AS ( SELECT DISTINCT c.mri_session_id, c.route_id, CAST(c.doj AS VARCHAR) AS doj FROM "user_interaction"."confirm_order_details" c WHERE c.__time >= TIMESTAMP '2026-04-19 18:30:00' AND c.__time < TIMESTAMP '2026-04-29 18:30:00' AND c.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND c.country = 'IND' AND c.status = 200 AND c.tin IS NOT NULL AND c.tin NOT IN ('', 'null') ), confirm_tagged AS ( SELECT co.mri_session_id, se.exp_variant, CASE WHEN sb.mri_session_id IS NOT NULL THEN 1 ELSE 0 END AS session_saw_boost, CASE WHEN bt.mri_session_id IS NOT NULL THEN 1 ELSE 0 END AS confirm_on_boosted_route FROM confirm_ok co INNER JOIN session_exp se ON se.mri_session_id = co.mri_session_id LEFT JOIN saw_boost_session sb ON sb.mri_session_id = co.mri_session_id LEFT JOIN boosted_route_tuple bt ON bt.mri_session_id = co.mri_session_id AND bt.route_id = co.route_id AND bt.doj = co.doj ) SELECT '20 to 29 April' AS month_period, exp_variant, COUNT(DISTINCT mri_session_id) AS overall_confirms, COUNT(DISTINCT CASE WHEN session_saw_boost = 1 THEN mri_session_id END) AS confirm_who_saw_boost, COUNT(DISTINCT CASE WHEN confirm_on_boosted_route = 1 THEN mri_session_id END) AS boost_confirms -- , -- CAST(COUNT(DISTINCT CASE WHEN session_saw_boost = 1 THEN mri_session_id END) AS DOUBLE) -- / NULLIF(COUNT(DISTINCT mri_session_id), 0) AS share_confirm_who_saw_boost_vs_overall, -- CAST(COUNT(DISTINCT CASE WHEN confirm_on_boosted_route = 1 THEN mri_session_id END) AS DOUBLE) -- / NULLIF(COUNT(DISTINCT mri_session_id), 0) AS share_boost_confirms_vs_overall, -- CAST(COUNT(DISTINCT CASE WHEN confirm_on_boosted_route = 1 THEN mri_session_id END) AS DOUBLE) -- / NULLIF(COUNT(DISTINCT CASE WHEN session_saw_boost = 1 THEN mri_session_id END), 0) -- AS share_boost_confirms_among_saw_boost FROM confirm_tagged GROUP BY 1, 2 ORDER BY 1, 2
